CREATE OR REPLACE FUNCTION calculate_csi(p_cntref character) RETURNS numeric AS $$
DECLARE
    v_authenscore numeric;
    v_cntuniqscore numeric;
    v_convnatval numeric;
    v_mediaratio numeric;
    v_txtuniq numeric;
    v_cas numeric;
    v_cms numeric;
    v_csi numeric;
BEGIN
    -- Get authenscore from moderationaction
    SELECT ma.authenscore INTO v_authenscore
    FROM moderationaction ma
    WHERE ma.macntref = p_cntref;

    -- Get cntuniqscore and mediaratio from contentbehavior
    SELECT cb.cntuniqscore, cb.mediaratio INTO v_cntuniqscore, v_mediaratio
    FROM contentbehavior cb
    WHERE cb.cntref = p_cntref;

    -- Get convnatval and txtuniq from messaginganalysis
    SELECT ma.convnatval, ma.txtuniq INTO v_convnatval, v_txtuniq
    FROM messaginganalysis ma
    WHERE ma.msgcntref = p_cntref;

    -- Handle missing scores - return NULL if any score is missing
    IF v_authenscore IS NULL OR v_cntuniqscore IS NULL OR v_convnatval IS NULL 
       OR v_mediaratio IS NULL OR v_txtuniq IS NULL THEN
        RETURN NULL;
    END IF;

    -- Calculate CAS = 0.3 * authenscore + 0.3 * cntuniqscore + 0.4 * convnatval
    v_cas := 0.3 * v_authenscore + 0.3 * v_cntuniqscore + 0.4 * v_convnatval;

    -- Calculate CMS = 0.4 * (1 - cntuniqscore) + 0.3 * mediaratio + 0.3 * txtuniq
    v_cms := 0.4 * (1 - v_cntuniqscore) + 0.3 * v_mediaratio + 0.3 * v_txtuniq;

    -- Calculate CSI = 0.7 * (1 - CMS) + 0.3 * CAS
    v_csi := 0.7 * (1 - v_cms) + 0.3 * v_cas;

    RETURN v_csi;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error calculating CSI for %: %', p_cntref, SQLERRM;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

